MATCH (source:PlantItem {tag: 'P-33901B'}), (v:Valve), (e:Equipment)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-48601B'}), (b:PlantItem {tag: 'M-48701'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'BFV-486001')+ (b)
} AS reachable

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'TIAH-170015'})
MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head)
RETURN DISTINCT equipment.tag AS tag ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-35801'}), (b:PlantItem {tag: 'D-35801'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'P-35801'}), (b:PlantItem {tag: 'D-35801'})
CALL {
  WITH a
  MATCH (a)-[:line_to*1..]->(v:Valve)
  RETURN collect(DISTINCT v.tag) AS downstreamTags
}
CALL {
  WITH b
  MATCH (v:Valve)-[:line_to*1..]->(b)
  RETURN collect(DISTINCT v.tag) AS upstreamTags
}
WITH [tag IN downstreamTags WHERE tag IN upstreamTags] AS valveTags
RETURN size(valveTags) AS valve_count, valveTags AS valve_tags

